entries[403511] = { ["name"] = "Soul Siphon", ["text"] = "Causes your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent.\n(Proc chance: 8%)" }
entries[403619] = { ["name"] = "Fel Armor", ["text"] = "28% of base mana\nInstant\nSurrounds the caster with fel energy, increasing spell damage and healing by 1 plus additional spell damage and healing equal to 50% of your Spirit. In addition, you regain 2% of your maximum health every 5 sec. Only one type of Armor spell can be active on the Warlock at any time. Lasts 30 min." }
