entries[403629] = { ["name"] = "Chaos Bolt", ["text"] = "7% of base mana 30 yd range\n2.5 sec cast 12 sec cooldown\nSends a bolt of chaotic fire at the enemy, dealing [source value] to [source value] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level.", ["unresolvedValues"] = true }
