entries[403858] = { ["name"] = "Haunt", ["text"] = "Gain the Haunt ability:\n\nUnleash a ghostly soul on an enemy, dealing [source value] to [source value] damage, and increasing all Shadow damage over time you deal to that target by 40% for 15 sec. When the Haunt ends or is dispelled, you will be healed for all the damage it dealt to your target.", ["unresolvedValues"] = true }
entries[403860] = { ["name"] = "Chaos Bolt", ["text"] = "Gain the Chaos Bolt ability:\n\nSends a bolt of chaotic fire at the enemy, dealing [source value] to [source value] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level.", ["unresolvedValues"] = true }
entries[403863] = { ["name"] = "Soul Siphon", ["text"] = "Gain the Soul Siphon ability:\n\nCauses your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent." }
entries[403868] = { ["name"] = "Master Channeler", ["text"] = "Gain the Master Channeler ability:\n\nYour Drain Life is no longer channeled, lasts 15 sec with a 15 sec cooldown, costs 100% more mana, and heals you for 50% more each time it deals damage." }
entries[403871] = { ["name"] = "Shadow Bolt Volley", ["text"] = "Gain the Shadow Bolt Volley ability:\n\nYour Shadow Bolt now strikes up to 5 targets within a chain distance of 10 yards, but for 30% reduced damage." }
entries[403872] = { ["name"] = "Lake of Fire", ["text"] = "Gain the Lake of Fire ability:\n\nYour Rain of Fire is no longer channeled, but gains a 8 sec cooldown." }
entries[403873] = { ["name"] = "Metamorphosis", ["text"] = "Gain the Metamorphosis ability:\n\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 50%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 10%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\nSearing Pain: Now instant.\n\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\nFear: Replaced with Menace.\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\nDemon Charge\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\nDemonic Howl\n\nForces all nearby enemies to focus attacks on you for 6 sec." }
entries[403919] = { ["name"] = "Engrave Gloves - Haunt", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Haunt rune:\n\nUnleash a ghostly soul on an enemy, dealing [source value] to [source value] damage, and increasing all Shadow damage over time you deal to that target by 40% for 15 sec. When the Haunt ends or is dispelled, you will be healed for all the damage it dealt to your target.", ["unresolvedValues"] = true }
entries[403920] = { ["name"] = "Engrave Cloak - Soul Siphon", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Soul Siphon rune:\n\nCauses your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent." }
entries[403925] = { ["name"] = "Engrave Gloves - Chaos Bolt", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Chaos Bolt rune:\n\nSends a bolt of chaotic fire at the enemy, dealing [source value] to [source value] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level.", ["unresolvedValues"] = true }
