entries[407613] = { ["name"] = "Beacon of Light", ["text"] = "7% of base mana 40 yd range\nInstant\nThe target becomes a Beacon of Light to all members of your party or raid within a 40 yard radius. Any heals you cast on party or raid members will also heal the Beacon for 75% of the amount healed. Only one target can be the Beacon of Light at a time. Lasts 1 hour." }
