entries[409554] = { ["name"] = "Explosive Shot", ["text"] = "Unlimited range\nYou fire an explosive charge into the enemy target, dealing (Ranged Attack Power * 0.14 + 10)-(Ranged Attack Power * 0.14 + 10) Fire damage. The charge will blast the target every second for an additional until cancelled. Cooldown shared with Arcane Shot." }
entries[409580] = { ["name"] = "Heart of the Lion", ["text"] = "8% of base mana\nInstant\nThe hunter invokes the heart of a lion, increasing total stats by 10% and Attack Power by 200 for all nearby allies, and increasing total stats for the Hunter by an additional 10%." }
entries[409583] = { ["name"] = "Heart of the Lion", ["text"] = "100 yd range\nInstant\nThe hunter invokes the heart of a lion, increasing total stats by 10% for all nearby allies, and increasing total stats for the Hunter by an additional 10%." }
entries[409593] = { ["name"] = "Kill Shot", ["text"] = "3% of base mana 35 yd range\n12 sec cooldown\nRequires Ranged Weapon\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", ["unresolvedValues"] = true }
entries[409687] = { ["name"] = "Dual Wield Specialization", ["text"] = "Increases the damage done by your offhand weapon by 60% and causes your Raptor Strike to strike with both weapons when you are dual-wielding." }
entries[409691] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 2 to 3." }
entries[409693] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 5." }
entries[409748] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 10 to 11." }
entries[409750] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 17." }
entries[409751] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 25." }
entries[409752] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 40." }
entries[409754] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 55." }
entries[409755] = { ["name"] = "Raptor Strike", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nA strong attack that increases melee damage by 70." }
entries[409805] = { ["name"] = "Wild Strikes", ["text"] = "Gain the Wild Strikes ability:\n\nWhile you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the target is already benefitting from Windfury Totem." }
entries[409809] = { ["name"] = "Survival Instincts", ["text"] = "Gain the Survival Instincts ability:\n\nWhen activated, this grants you 30% of your maximum health and increases all non-Physical healing you deal by 20% for 20 sec. After the effect expires, the health is lost. Useable in all forms except Moonkin Form.\n\nIn addition, you regenerate 5 rage every time you dodge while in Bear Form or Dire Bear Form, 10 energy while in Cat Form, or 1% of your maximum mana while in any other form." }
entries[409810] = { ["name"] = "Wild Growth", ["text"] = "Gain the Wild Growth ability:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] over 7 sec. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.", ["unresolvedValues"] = true }
entries[409813] = { ["name"] = "Eclipse", ["text"] = "Gain the Eclipse ability:\n\nStarfire increases the critical strike chance of your next two Wraths by 30%, and Wrath reduces the cast time of your next Starfire by 1.0 sec, both effects stacking up to 4 charges. Both spells also gain 70% chance at all times to not lose casting time when you take damage." }
entries[409819] = { ["name"] = "Savage Roar", ["text"] = "Gain the Savage Roar ability:\n\nFinishing move that increases physical damage done by 30% while in Cat Form. Lasts longer per combo point:\n1 point : 14 seconds\n2 points: 19 seconds\n3 points: 24 seconds\n4 points: 29 seconds\n5 points: 34 seconds" }
entries[409824] = { ["name"] = "Lifebloom", ["text"] = "Reduces the global cooldown on your Rejuvenation and Lifebloom abilities by 0.5 sec and you gain the Lifebloom ability:\n\nHeals the target for [source value] over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals for [source value] and the Druid regains half the cost of the spell. This effect can stack up to 3 times on the same target.", ["unresolvedValues"] = true }
entries[409826] = { ["name"] = "Nature's Fury", ["text"] = "Gain the Nature's Fury ability:\n\nIncreases your healing power by 90% of your Nature spell damage for 30 sec." }
entries[409828] = { ["name"] = "Mangle", ["text"] = "Gain the Mangle (Bear) ability and replace your Claw ability with Mangle (Cat). This ability benefits from and triggers all effects associated with Claw and Maul.\n\nMangle the target for 160% normal damage and cause the target to take 30% additional damage from Bleed effects and Shred for 1 min. This ability benefits from and triggers all effects associated with Claw and Maul.\n\nHitting a target with Mangle (Bear) also grants you 4 Attack Power for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n\nMangle the target for 270% normal damage and cause the target to take 30% additional damage from Bleed effects and Shred for 1 min. Awards 1 combo point. This ability benefits from and triggers all effects associated with Claw and Maul." }
entries[409830] = { ["name"] = "Nourish", ["text"] = "Gain the Nourish ability:\n\nHeals a friendly target for [source value] to [source value]. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth.", ["unresolvedValues"] = true }
entries[409831] = { ["name"] = "Dreamstate", ["text"] = "Gain the Dreamstate ability:\n\nYour damaging non-periodic spell critical strikes or any damage from Starsurge grant you 50% of your mana regeneration while casting for 8 sec and increase Arcane and Nature damage dealt to non-player targets by 20% for 12 sec." }
entries[409832] = { ["name"] = "Fury of Stormrage", ["text"] = "Gain the Fury of Stormrage ability:\n\nReduces the mana cost of Wrath by 100% and each time you deal damage with Wrath you have a 12% chance for your next cast of Healing Touch within 15 sec to be instant and castable in any shapeshift form. Allows Wrath to be cast while in Tree of Life form." }
entries[409856] = { ["name"] = "Spirit Ritual", ["text"] = "30 yd range\nChanneled (10 min cast)\nBegins a ritual to free the spirit of a fallen adventurer." }
entries[409858] = { ["name"] = "Dummy Trigger" }
entries[409906] = { ["name"] = "Beacon of Light", ["text"] = "Gain the Beacon of Light ability:\n\nThe target becomes a Beacon of Light to all members of your party or raid within a 40 yard radius. Any heals you cast on party or raid members will also heal the Beacon for 75% of the amount healed. Only one target can be the Beacon of Light at a time. Lasts 1 hour." }
entries[409911] = { ["name"] = "Hand of Reckoning", ["text"] = "Gain the Hand of Reckoning ability:\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\nWhile you know this ability, the threat bonus from Righteous Fury is increased to 80% and Righteous Fury causes you to gain mana when healed by others equal to 25% of the amount healed. Additionally, while Righteous Fury is active, damage which takes you below 35% health is reduced by 20%. Righteous Fury will remain active until cancelled." }
entries[409914] = { ["name"] = "Crusader Strike", ["text"] = "Gain the Crusader Strike ability:\n\nAn instant strike that causes 75% weapon damage as Holy and regenerates 5% of your maximum mana. The duration of all Judgement effects on the target is refreshed to 30 sec." }
entries[409918] = { ["name"] = "Inspiration (Judgement)" }
entries[409920] = { ["name"] = "Learn Relic (Judgement)" }
entries[409922] = { ["name"] = "Hammer of the Righteous", ["text"] = "Gain the Hammer of the Righteous ability:\n\nHammer the current target and up to 3 additional nearby targets, causing 4 times your main hand damage per second as Holy damage." }
entries[409924] = { ["name"] = "Divine Storm", ["text"] = "Gain the Divine Storm ability:\n\nAn instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused." }
entries[409925] = { ["name"] = "Divine Light", ["text"] = "Gain the Divine Light ability:\n\nHeals a friendly target for [source value] to [source value]. 50% of any excess healing on the target is converted into an absorption shield that lasts 15 sec. Multiple casts of Divine Light do not accumulate this shield.\n\nDivine Light benefits from all talents and effects that trigger from or modify Holy Light.", ["unresolvedValues"] = true }
entries[409930] = { ["name"] = "Libram of Judgement" }
entries[409932] = { ["name"] = "Aura Mastery", ["text"] = "Gain the Aura Mastery ability:\n\nCauses your Concentration Aura to make all affected targets immune to Silence and Interrupt effects and improves the effect of all other auras by 100%. Lasts 6 sec." }
entries[409933] = { ["name"] = "Avenger's Shield", ["text"] = "Gain the Avenger's Shield ability:\n\nHurls a holy shield at the enemy, dealing [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell Power + 0.091 * Attack Power] to [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell Power + 0.091 * Attack Power] Holy damage, Dazing them and then jumping to additional nearby enemies. Affects 3 total targets. Lasts 5 sec." }
entries[409934] = { ["name"] = "Avenging Wrath", ["text"] = "Gain the Avenging Wrath ability:\n\nIncreases all damage and healing caused by 20% for 20 sec. Causes Forbearance and cannot be used while Forebearance is active." }
entries[409935] = { ["name"] = "Hand of Sacrifice", ["text"] = "Gain the Hand of Sacrifice ability:\n\nCauses target party or raid member to transfer 30% of damage taken to the caster. Lasts 12 sec or until the caster has transferred 100% of their maximum health." }
entries[409936] = { ["name"] = "Inspiration Exemplar", ["text"] = "Gain the Inspiration Exemplar\nability:\n\nYour inspiring presence periodically dispels Fear and Sleep effects on nearby party members." }
entries[409938] = { ["name"] = "Fire Nova", ["text"] = "Gain the Fire Nova ability, replacing your Fire Nova Totem:\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location." }
entries[409940] = { ["name"] = "Dual Wield Specialization", ["text"] = "Gain the Dual Wield Specialization ability:\n\nIncreases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%." }
entries[409941] = { ["name"] = "Water Shield", ["text"] = "Gain the Water Shield ability:\n\nThe caster is surrounded by 3 globes of water, granting 1% of your maximum mana per 5 sec. When a spell, melee or ranged attack hits the caster, 4% of maximum mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time." }
entries[409943] = { ["name"] = "Shield Mastery", ["text"] = "Gain the Shield Mastery ability:\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\nIn addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec." }
entries[409944] = { ["name"] = "Ancestral Guidance", ["text"] = "Gain the Ancestral Guidance ability:\n\nFor the next 10 sec, 25% of your damage is converted to healing on up to 3 nearby party members, and 100% of your healing is converted to damage on your most recent Flame Shock target." }
entries[409945] = { ["name"] = "Overload", ["text"] = "Gain the Overload ability:\n\nGives your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells a 60% chance to cast a second, similar spell on the same target at no additional cost that causes half damage or healing and no threat." }
entries[409946] = { ["name"] = "Maelstrom Weapon", ["text"] = "Gain the Maelstrom Weapon ability:\n\nWhen you deal damage with a melee attack, you have a chance to reduce the cast time and mana cost of your next Lightning Bolt, Chain Lightning, Lesser Healing Wave, or Lava Burst spell by 20%. Chance increased by 50% while your main hand weapon is enchanted with Windfury Weapon and by another 50% if wielding a two-handed weapon. Stacks up to 5 times. Lasts 30 sec." }
entries[409947] = { ["name"] = "Earth Shield", ["text"] = "Gain the Earth Shield ability:\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [source value]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.", ["unresolvedValues"] = true }
entries[409951] = { ["name"] = "Spirit of the Alpha", ["text"] = "Gain the Spirit of the Alpha ability:\n\nInfuses the target with the spirit of an alpha wolf, increasing all threat generated by the target by 45% for 30 min. Limit 1 target. If cast on a target other than self, the Shaman also gains Loyal Beta, increasing Physical damage done by 5% and reducing all threat generated by 30% for 30 min. A target cannot have both Spirit of the Alpha and Loyal Beta at the same time." }
entries[409952] = { ["name"] = "Lava Burst", ["text"] = "Gain the Lava Burst ability:\n\nYou hurl molten lava at the target, dealing [source value] to [source value] Fire damage. If your Flame Shock is on the target, Lava Burst will deal a critical strike.", ["unresolvedValues"] = true }
entries[409953] = { ["name"] = "Lava Lash", ["text"] = "Gain the Lava Lash ability:\n\nYou charge your off-hand weapon with lava, instantly dealing 100% off-hand Weapon damage. Damage is increased by 150% if your off-hand weapon is enchanted with Flametongue." }
entries[409954] = { ["name"] = "Riptide", ["text"] = "Gain the Riptide ability:\n\nHeals a friendly target for [source value] to [source value] and another [source value] over 15 sec. Your Chain Heals cast on that primary target within 15 sec will increase the amount of the Chain Heal by 25%. This spell also triggers Ancestral Awakening.", ["unresolvedValues"] = true }
entries[409955] = { ["name"] = "Way of Earth", ["text"] = "Gain the Way of Earth ability:\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 25% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards." }
entries[409957] = { ["name"] = "Steady Shot", ["text"] = "Gain the Steady Shot ability:\n\nA steady shot that causes 100% ranged weapon damage." }
entries[409958] = { ["name"] = "Master Marksman", ["text"] = "Gain the Master Marksman ability:\n\nIncreases your critical strike chance by 5%, and reduces the Mana cost of all your Shot abilities by 25%." }
entries[409959] = { ["name"] = "Expose Weakness", ["text"] = "Gain the Expose Weakness ability:\n\nYour melee and ranged criticals increase your attack power by 40% of your current Agility for 7 sec." }
entries[409960] = { ["name"] = "Cobra Slayer", ["text"] = "Gain the Cobra Slayer ability:\n\nMongoose Bite now has a 10% chance to activate on each of your melee attacks, a 100% chance when an enemy dodges. This chance accumulates, with the chance rising by 10% from each subsequent attack if it does not reset. Mongoose Bite also deals additional damage equal to 45% of your Attack Power." }
entries[409961] = { ["name"] = "Dual Wield Specialization", ["text"] = "Gain the Dual Wield Specialist ability:\n\nIncreases the damage done by your offhand weapon by 60% and causes your Raptor Strike to strike with both weapons when you are dual-wielding." }
entries[409962] = { ["name"] = "Beast Mastery", ["text"] = "Gain the Beast Mastery ability:\n\nYour pet's damage and health are increased by 15%, and its Focus regeneration by 50%. In addition, your pet's Growl now also Taunts the target to attack it for 3 sec." }
entries[409963] = { ["name"] = "Summon Spirit" }
entries[409968] = { ["name"] = "Trap Launcher", ["text"] = "Gain the Trap Launcher ability:\n\nYour Freezing, Immolation, and Explosive Traps can now be placed at any location within 35 yards. Additionally, your Fire-based and Frost-based traps now have separate shared cooldowns." }
entries[409974] = { ["name"] = "Kill Shot", ["text"] = "Gain the Kill Shot ability:\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", ["unresolvedValues"] = true }
entries[409976] = { ["name"] = "Chimera Shot", ["text"] = "Gain the Chimera Shot ability:\n\nYou deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\nSerpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\nViper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\nScorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute." }
entries[409978] = { ["name"] = "Explosive Shot", ["text"] = "Gain the Explosive Shot ability:\n\nYou fire an explosive charge into the enemy target, dealing [Ranged Attack Power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged Attack Power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Fire damage to all enemies within 8 yards. The charge will deal damage again every second for an additional 2 sec." }
entries[409979] = { ["name"] = "Lone Wolf", ["text"] = "Gain the Lone Wolf ability:\n\nYou deal 25% increased damage with all attacks while you do not have an active pet." }
entries[409988] = { ["name"] = "Force Player Cast Delayed Banish" }
entries[409999] = { ["name"] = "Engrave Gloves - Beacon of Light", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Beacon of Light rune:\n\nThe target becomes a Beacon of Light to all members of your party or raid within a 40 yard radius. Any heals you cast on party or raid members will also heal the Beacon for 75% of the amount healed. Only one target can be the Beacon of Light at a time. Lasts 1 hour." }
entries[410001] = { ["name"] = "Engrave Gloves - Hand of Reckoning", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Hand of Reckoning rune:\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\nWhile you know this ability, the threat bonus from Righteous Fury is increased to 80% and Righteous Fury causes you to gain mana when healed by others equal to 25% of the amount healed. Additionally, while Righteous Fury is active, damage which takes you below 35% health is reduced by 20%. Righteous Fury will remain active until cancelled." }
entries[410002] = { ["name"] = "Engrave Gloves - Crusader Strike", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Crusader Strike rune:\n\nAn instant strike that causes 75% weapon damage as Holy and regenerates 5% of your maximum mana. The duration of all Judgement effects on the target is refreshed to 30 sec." }
