entries[412510] = { ["name"] = "Mass Regeneration", ["text"] = "45% of base mana 40 yd range\nChanneled (3 sec cast) 12 sec cooldown\nHeals all of target player's party members within 43.5 yards of target player for [source value] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.", ["unresolvedValues"] = true }
entries[412513] = { ["name"] = "Gladiator Stance", ["text"] = "Instant 1 sec cooldown\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\nWhile wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances." }
