entries[415460] = { ["name"] = "Burnout", ["text"] = "Gain the Burnout ability:\n\nIncreases your spell critical strike chance with all spells by 15%, but your non-periodic spell critical strikes now have an additional mana cost of 1% of your base mana." }
entries[415467] = { ["name"] = "Mass Regeneration", ["text"] = "Gain the Mass Regeneration ability:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.", ["unresolvedValues"] = true }
entries[415481] = { ["name"] = "Pain and Suffering", ["text"] = "Gain the Pain and Suffering ability:\n\nMind Blast, Mind Spike, and Mind Flay refresh the duration of your one of your Shadow Word: Pain, Void Plague, or Vampiric Touch abilities on the target back to its maximum duration. The ability with the shortest remaining duration will always be the one refreshed." }
entries[415596] = { ["name"] = "Shield Mastery", ["text"] = "Gain the Shield Mastery ability:" }
entries[415598] = { ["name"] = "Gladiator Stance", ["text"] = "Gain the Gladiator Stance ability:\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\nWhile wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances." }
entries[415599] = { ["name"] = "Single-Minded Fury", ["text"] = "Gain the Single-Minded Fury ability:\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 4% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target." }
entries[415604] = { ["name"] = "Everlasting Affliction", ["text"] = "Gain the Everlasting Affliction ability:\n\nDrain Life, Drain Soul, Shadowbolt, Shadow Cleave, Searing Pain, Incinerate, and Haunt refresh the duration of your Corruption on the target back to its maximum duration." }
entries[415605] = { ["name"] = "Demonic Tactics", ["text"] = "Gain the Demonic Tactics ability:\n\nIncreases the melee and spell critical strike chance of you and your pet by 10%." }
entries[415703] = { ["name"] = "Sacred Shield", ["text"] = "Gain the Sacred Shield ability:\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [source value] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time.", ["unresolvedValues"] = true }
entries[415706] = { ["name"] = "The Art of War", ["text"] = "Gain the The Art of War ability:\n\nYour melee critical strikes reduce the remaining cooldown on Exorcism by 2 sec, and the mana cost of Exorcism is reduced by 80%." }
entries[415709] = { ["name"] = "Survival of the Fittest", ["text"] = "Gain the Survival of the Fittest ability:\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form." }
entries[415712] = { ["name"] = "Power Surge", ["text"] = "Gain the Power Surge ability:\n\nEach time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect." }
entries[415713] = { ["name"] = "Mental Dexterity", ["text"] = "Gain the Mental Dexterity ability:\n\nDealing damage with Stormstrike increases your Attack Power by 150% of your Intellect, and your spell damage by 35% of your total Attack Power for 30 sec." }
entries[415714] = { ["name"] = "Healing Rain", ["text"] = "Gain the Healing Rain ability:\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [source value] every second.", ["unresolvedValues"] = true }
entries[415717] = { ["name"] = "Catlike Reflexes", ["text"] = "Gain the Catlike Reflexes ability:\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%." }
entries[415718] = { ["name"] = "Aspect of the Viper", ["text"] = "Gain the Aspect of the Viper ability:\n\nThe hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time." }
entries[415719] = { ["name"] = "Lock and Load", ["text"] = "Gain the Lock and Load ability:\n\nEach time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown." }
entries[415720] = { ["name"] = "Kill Shot", ["text"] = "Gain the Kill Shot ability:\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", ["unresolvedValues"] = true }
entries[415723] = { ["name"] = "Melee Specialist", ["text"] = "Gain the Melee Specialist ability:\n\nYour Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 40% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike." }
entries[415725] = { ["name"] = "Waylay", ["text"] = "Gain the Waylay ability:\n\nYour Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by 10%, and reducing movement speed by 50% for 8 sec." }
entries[415729] = { ["name"] = "Enlightenment", ["text"] = "Gain the Enlightenment ability:\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting." }
entries[415734] = { ["name"] = "Spellfrost Bolt", ["text"] = "Gain the Spellfrost Bolt ability:\n\nLaunches a bolt of spellfrost at the enemy, causing [source value] to [source value] Spellfrost damage and slowing movement speed by 40% for 9 sec. This spell will be checked against the lower of the target's Frost and Arcane resists and counts as both Frost and Arcane damage.", ["unresolvedValues"] = true }
entries[415737] = { ["name"] = "Serendipity", ["text"] = "Gain the Serendipity ability:\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times." }
entries[415738] = { ["name"] = "Mind Sear", ["text"] = "Gain the Mind Sear ability:\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [source value] to [source value] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target.", ["unresolvedValues"] = true }
entries[415739] = { ["name"] = "Strength of Soul", ["text"] = "Lesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal." }
entries[415740] = { ["name"] = "Strength of Soul", ["text"] = "Gain the Strength of Soul ability:\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal." }
entries[415743] = { ["name"] = "Blood Surge", ["text"] = "Gain the Blood Surge ability:\n\nHeroic Strike, Bloodthirst, and Whirlwind have a 30% chance to make your next Slam within 15 sec instant, strike with both melee weapons, and cost no Rage." }
entries[415744] = { ["name"] = "Precise Timing", ["text"] = "Gain the Precision Timing ability:\n\nSlam is now instant but has a 6 sec cooldown." }
entries[415745] = { ["name"] = "Focused Rage", ["text"] = "Gain the Focused Rage ability:\n\nReduces the rage cost of your offensive abilities by 3." }
entries[415749] = { ["name"] = "Demonic Knowledge", ["text"] = "Gain the Demonic Knowledge ability:\n\nIncreases your spell damage and healing by a value equal to 3% of your Demon pet's total Stamina plus Intellect." }
entries[415750] = { ["name"] = "Incinerate", ["text"] = "Gain the Incinerate ability:\n\nBurn your enemy for [source value] to [source value] damage and increase all Fire damage you deal by 40% for the next 15 sec.", ["unresolvedValues"] = true }
entries[415751] = { ["name"] = "Dance of the Wicked", ["text"] = "Gain the Dance of the Wicked ability:\n\nYou and your demon pet gain dodge chance equal to 70% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain 2% of maximum mana." }
entries[415755] = { ["name"] = "Guarded by the Light", ["text"] = "Gain the Guarded by the Light ability:\n\nEach time you hit a target with your melee weapon, you gain 5% of your maximum mana per 3 sec for 15 sec, but the amount healed by your Healing spells is reduced by 50% during this mana regeneration." }
entries[415756] = { ["name"] = "Aura Mastery", ["text"] = "Gain the Aura Mastery ability:\n\nCauses your Concentration Aura to make all affected targets immune to Silence and Interrupt effects and improves the effect of all other auras by 100%. Lasts 6 sec." }
entries[415759] = { ["name"] = "Skull Bash", ["text"] = "Gain the Skull Bash ability:\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge." }
entries[415760] = { ["name"] = "Lacerate", ["text"] = "Gain the Lacerate ability:\n\nLacerates the enemy target, making them bleed for [source value] damage over 15 sec plus 20% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target.", ["unresolvedValues"] = true }
entries[415761] = { ["name"] = "Living Seed", ["text"] = "Gain the Living Seed ability:\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec." }
entries[415762] = { ["name"] = "Elune's Fires", ["text"] = "Gain the Elune's Fires ability:\n\nSome of your spells and abilities extend the duration of your damage and healing over time effects on their target:\n\nStarfire extends Moonfire by 6 sec.\nWrath extends Sunfire by 3 sec.\nRegrowth extends Rejuvenation by 6 sec.\nShred extends Rip by 2 sec.\n\nEach effect can only be extended up to its initial duration." }
entries[415768] = { ["name"] = "Burn", ["text"] = "Gain the Burn ability:\n\nYour Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect." }
entries[415813] = { ["name"] = "Greater Ghost Wolf", ["text"] = "Your Ghost Wolf ability can now be used indoors, and reduces all damage you take by 10% while active." }
entries[415816] = { ["name"] = "Wyvern Strike", ["text"] = "Gain the Wyvern Strike ability:\n\nReplaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals 140% weapon damage and causes the target to Bleed for damage over time.\n\nWyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook." }
entries[415817] = { ["name"] = "Rapid Killing", ["text"] = "Gain the Rapid Killing ability:\n\nReduces the cooldown on Rapid Fire by 80%, Rapid Fire now also grants 40% increased melee attack speed, and your next Shot ability within 20 sec after killing a target worth experience or honor deals 20% increased damage." }
entries[415818] = { ["name"] = "Sniper Training", ["text"] = "Gain the Sniper Training ability:\n\nYour Shot abilities gain 2% increased critical strike chance while you have not moved for the last 2 sec, stacking every sec up to 5 times. At 2 or more stacks, your Aimed Shot becomes instant. While moving, you will lose 1 stack per sec." }
entries[415822] = { ["name"] = "Raptor Fury", ["text"] = "Gain the Raptor Fury ability:\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect." }
entries[415918] = { ["name"] = "Engrave Cloak - Crimson Tempest", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Crimson Tempest rune:\n\nFinishing move that slashes all enemies within 8 yards, causing victims to Bleed over time. Lasts longer and deals more damage per combo point.\n\n1 point : (Attack Power * 0.30) damage over 4 sec.\n2 points: (Attack Power * 0.45) damage over 6 sec.\n3 points: (Attack Power * 0.60) damage over 8 sec.\n4 points: (Attack Power * 0.75) damage over 10 sec.\n5 points: (Attack Power * 0.90) damage over 12 sec.\n\nCrimson Tempest benefits from all talents and effects that trigger from or modify Rupture." }
